function enhanceMarketplaceDistances(){if(!dashboard)return;document.querySelectorAll('#availableJobGrid .market-job').forEach(card=>{if(card.querySelector('.distance-label'))return;const title=card.querySelector('h3')?.textContent,job=dashboard.availableJobs.find(item=>item.title===title);if(job&&Number.isFinite(job.distanceMiles)){const label=document.createElement('small');label.className='distance-label';label.textContent=job.distanceMiles?`${job.distanceMiles} miles from your marketplace location`:'In your marketplace city';card.querySelector('.job-topline')?.appendChild(label)}});document.querySelectorAll('#directoryGrid .directory-card').forEach(card=>{if(card.querySelector('.distance-label'))return;const name=card.querySelector('h3')?.textContent,company=dashboard.directory.find(item=>item.name===name);if(company&&Number.isFinite(company.distanceMiles)){const label=document.createElement('small');label.className='distance-label';label.textContent=company.distanceMiles?`${company.distanceMiles} miles away`:'In your marketplace city';card.querySelector('div')?.appendChild(label)}})}
let reviewProfileLoading=false,lastReviewProfile='';async function enhanceTrustProfileReviews(){if(reviewProfileLoading||typeof viewedProfileId==='undefined'||!viewedProfileId)return;const root=document.getElementById('trustProfileContent');if(!root||!root.querySelector('.trust-profile-heading')||root.querySelector('.trust-reviews-section')||lastReviewProfile===viewedProfileId)return;reviewProfileLoading=true;try{const p=await api(`/api/profiles/${viewedProfileId}`),summary=p.reviewSummary,section=document.createElement('section');section.className='trust-reviews-section';section.innerHTML=`<h3>Verified project reviews</h3>${summary.count?`<div class="trust-review-summary"><strong>${summary.overallRating} / 5</strong><span>${summary.count} completed-job review${summary.count===1?'':'s'} · ${summary.recommends} recommend</span></div><div>${summary.reviews.map(review=>`<article class="trust-review-card"><span class="trade-pill">${escapeHtml(review.trade)}</span><strong>${review.overallRating} / 5</strong><p>${escapeHtml(review.body||'Verified rating from a completed Trades job.')}</p><small>${review.recommends?'Recommended by project partner':'Completed-job review'} · ${new Date(review.createdAt).toLocaleDateString()}</small></article>`).join('')}</div>`:'<div class="list-empty">No verified completed-job reviews yet.</div>'}`;root.querySelector('.due-diligence-note')?.before(section);lastReviewProfile=viewedProfileId}catch(error){console.error(error)}finally{reviewProfileLoading=false}}
new MutationObserver(()=>{enhanceMarketplaceDistances();enhanceTrustProfileReviews()}).observe(document.body,{childList:true,subtree:true});const polishRefresh=refresh;refresh=async function(){await polishRefresh();enhanceMarketplaceDistances()};
